private float CalculateScore(AppUser user, AppTask task)
{
    if (user == null || task == null) return 0f;
    float score = 0;
    string categoryName = task.Category?.Name?.ToLower() ?? string.Empty;
    if (user.UserGoals?.Contains(categoryName) == true) score += 0.4f;
    if (user.Strengths?.Any(s => task.Description?.Contains(s, StringComparison.OrdinalIgnoreCase) == true) == true) score += 0.25f;
    if (task.EstimatedMinutes.HasValue && user.DailyAvailableMinutes.HasValue && task.EstimatedMinutes <= user.DailyAvailableMinutes) score += 0.2f;
    if (IsMatchingDifficulty(task, user.DifficultyPreference)) score += 0.15f;
    return score;
}

